$ErrorActionPreference='Stop';$o=[ordered]@{Ok=$false;RebootRequired=$false;Error='';Updates=@()};try{$s=New-Object -ComObject Microsoft.Update.Session;$q=$s.CreateUpdateSearcher();$q.Online=$false;$r=$q.Search('IsInstalled=0 and IsHidden=0');$o.Updates=@($r.Updates | ForEach-Object { $u=$_;$m='';try{$m=[string]$u.DriverModel}catch{};[pscustomobject]@{Id=[string]$u.Identity.UpdateID;Title=[string]$u.Title;Kb=(@($u.KBArticleIDs | ForEach-Object { 'KB' + [string]$_ }) -join ', ');Driver=([int]$u.Type -eq 2);Category=(@($u.Categories | ForEach-Object { [string]$_.Name } | Select-Object -First 2) -join ', ');SizeBytes=[string]$u.MaxDownloadSize;Downloaded=[bool]$u.IsDownloaded;MayNeedRestart=([int]$u.InstallationBehavior.RebootBehavior -ne 0);Severity=[string]$u.MsrcSeverity;DriverModel=$m} });try{$o.RebootRequired=[bool](New-Object -ComObject Microsoft.Update.SystemInfo).RebootRequired}catch{};$o.Ok=$true}catch{$o.Error=[string]$_.Exception.Message};[pscustomobject]$o | ConvertTo-Json -Compress -Depth 4